ALTER TABLE `ServiceRequest` MODIFY `status` ENUM('pending','confirmed','assigned','in_progress','waiting_customer_approval','completed','cancelled') NOT NULL DEFAULT 'pending';
CREATE TABLE `ServiceQuote` (`id` VARCHAR(191) NOT NULL,`serviceRequestId` VARCHAR(191) NOT NULL,`version` INTEGER NOT NULL,`diagnosis` TEXT NOT NULL,`labor` DECIMAL(12,2) NOT NULL DEFAULT 0,`parts` DECIMAL(12,2) NOT NULL DEFAULT 0,`travel` DECIMAL(12,2) NOT NULL DEFAULT 0,`other` DECIMAL(12,2) NOT NULL DEFAULT 0,`total` DECIMAL(12,2) NOT NULL,`status` ENUM('draft','sent','approved','rejected','superseded') NOT NULL DEFAULT 'draft',`validUntil` DATETIME(3) NOT NULL,`createdBy` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `ServiceQuote_serviceRequestId_version_key`(`serviceRequestId`,`version`),INDEX `ServiceQuote_serviceRequestId_status_idx`(`serviceRequestId`,`status`),PRIMARY KEY (`id`),CONSTRAINT `ServiceQuote_serviceRequestId_fkey` FOREIGN KEY (`serviceRequestId`) REFERENCES `ServiceRequest`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `QuoteApproval` (`id` VARCHAR(191) NOT NULL,`quoteId` VARCHAR(191) NOT NULL,`version` INTEGER NOT NULL,`decision` ENUM('approved','rejected') NOT NULL,`actorType` VARCHAR(191) NOT NULL,`actorId` VARCHAR(191) NULL,`channel` VARCHAR(191) NOT NULL,`evidence` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `QuoteApproval_quoteId_decision_idx`(`quoteId`,`decision`),PRIMARY KEY (`id`),CONSTRAINT `QuoteApproval_quoteId_fkey` FOREIGN KEY (`quoteId`) REFERENCES `ServiceQuote`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ServicePayment` (`id` VARCHAR(191) NOT NULL,`serviceRequestId` VARCHAR(191) NOT NULL,`amount` DECIMAL(12,2) NOT NULL,`method` VARCHAR(191) NOT NULL,`reference` VARCHAR(191) NULL,`receivedBy` VARCHAR(191) NOT NULL,`receivedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `ServicePayment_serviceRequestId_receivedAt_idx`(`serviceRequestId`,`receivedAt`),PRIMARY KEY (`id`),CONSTRAINT `ServicePayment_serviceRequestId_fkey` FOREIGN KEY (`serviceRequestId`) REFERENCES `ServiceRequest`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
